                'order_id' => $order->get_order_number(),
                'product_name' => $item->get_name(),
                'price' => $price,
                'quantity' => $quantity,
                'type' => 'credit',
                'total' => $price * $quantity
            );
        } else {
            $formatted_data[] = array(
                'date' => $order->get_date_created(),
                'order_id' => $order->get_order_number(),
                'product_name' => $item->get_name(),
                'price' => $price,
                'quantity' => $quantity,
                'type' => 'debit',
                'total' => $price * $quantity
            );
        }
    }

    return $formatted_data;
}

