To create a simple toast notification using React context, follow these steps:

1. Create a `ToastContext` file:

```javascript
import { createContext, useState } from 'react';

const ToastContext = createContext({});

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
  };

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. In your main application component, wrap the content with `ToastProvider`:

```javascript
import React from 'react';
import ToastContext from './ToastContext';

function App() {
  return (
    <ToastContext.Provider>
      {/* Your app content here */}
    </ToastContext.Provider>
  );
}

export default App;
```

3. Now, you can use the `ToastContext` in any component to display toast notifications:

```javascript
import React from 'react';
import { useContext } from 'react';
import ToastContext from './ToastContext';

function MyComponent() {
  const { toasts, addToast } = useContext(ToastContext);

  const handleClick = () => {
    addToast('This is a toast notification!');
  };

  return (
    <div>
      <button onClick={handleClick}>Add Toast</button>
      <ul>
        {toasts.map((toast) => (
          <li key={toast}>{toast}</li>
        ))}
      </ul>
    </div>
  );
}

export default MyComponent;
```

