Here's a simple React utility to remove widows. This component will check if the text contains any words that are wider than the container and adjust the font size accordingly to prevent widows.

```javascript
import React, { useRef, useState } from 'react';

const RemoveWidows = ({ children }) => {
  const textRef = useRef(null);
  const [fontSize, setFontSize] = useState(16);

  const handleResize = () => {
    const containerWidth = textRef.current.offsetWidth;
    const textWidth = textRef.current.scrollWidth;
    const words = textRef.current.textContent.split(' ');

    let adjustedFontSize = fontSize;

    for (let i = 0; i < words.length; i++) {
      const wordWidth = words[i].offsetWidth;

      if (wordWidth > containerWidth) {
        adjustedFontSize -= 2;
      }
    }

    setFontSize(adjustedFontSize);
  };

  return (
    <div ref={textRef} onResize={handleResize}>
      <style>{`
        .remove-widows {
          font-size: ${fontSize}px;
        }
      `}</style>
      {children}
    </div>
  );
};

export default RemoveWidows;
```

