// utils/redis.js
class RedisClient {
  constructor(host, port, db) {
    this.client = require("redis").createClient({
      host,
      port,
      db,
      on: "error",
      (err) => console.error(`Error with Redis: ${err}`),
    });
  }

  async isAlive() {
    try {
      await this.client.connect();
      return true;
    } catch (err) {
      return false;
    }
  }

  async get(key) {
    const result = await this.client.get(key);
    return result || null;
  }

  async set(key, value, duration) {
    await this.client.setex(key, duration, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

